package com.kuaixietech.refunds;
import com.kuaixietech.payments.PaymentModels.Merchant;
import com.kuaixietech.service.finance.impl.AtomicMoneyService;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.refunds.RefundModels.*;
@Service
public class RefundTransactions {
 private final RefundStore store;private final AtomicMoneyService money;
 public RefundTransactions(RefundStore store,AtomicMoneyService money){this.store=store;this.money=money;}
 private ResponseStatusException reject(String code){return new ResponseStatusException(HttpStatus.CONFLICT,code);}
 private void changed(int n){if(n!=1)throw new IllegalStateException("REFUND_CONCURRENT_CHANGE");}
 private record Locked(Map<String,Object> payment,Map<String,Object> refund){}
 private Locked lock(String id){var initial=store.refund(id);if(initial==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"REFUND_NOT_FOUND");var payment=store.row("SELECT * FROM t_currency_payments WHERE id=? FOR UPDATE",initial.get("payment_id"));var refund=store.row("SELECT * FROM t_payment_refunds WHERE id=? FOR UPDATE",id);if(payment==null||refund==null)throw new IllegalStateException("REFUND_SOURCE_UNAVAILABLE");return new Locked(payment,refund);}
 @Transactional public Map<String,Object> reserve(String user,Create input){String request=UUID.fromString(input.requestId()).toString(),id=UUID.nameUUIDFromBytes(("recharge-refund:"+user+":"+request).getBytes(StandardCharsets.UTF_8)).toString().replace("-","");var payment=store.row("SELECT * FROM t_currency_payments WHERE id=? AND user_id=? FOR UPDATE",input.paymentId(),user);if(payment==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"REFUND_SOURCE_UNAVAILABLE");var existing=store.row("SELECT * FROM t_payment_refunds WHERE user_id=? AND request_id=? FOR UPDATE",user,request);if(existing!=null){if(!input.paymentId().equals(existing.get("payment_id"))||!input.reason().trim().equals(existing.get("reason")))throw reject("REFUND_REQUEST_REUSED");return existing;}
  if(!"paid".equals(payment.get("status"))||!"CNY".equals(payment.get("base_currency"))||!"CNY".equals(payment.get("payment_currency"))||((Number)payment.get("payment_minor_digits")).intValue()!=2||RefundStore.minor(payment.get("base_minor")).signum()<=0||RefundStore.minor(payment.get("payment_minor")).signum()<=0)throw reject("REFUND_SOURCE_NOT_ELIGIBLE");
  Merchant merchant=store.merchant(payment);if(!Objects.equals(merchant.id(),payment.get("merchant_id"))||!Set.of("wechat_native_v3","wechat_jsapi_v3","wechat_app_v3","alipay_rsa2").contains(merchant.adapter()))throw reject("REFUND_CHANNEL_NOT_SUPPORTED");
  if(store.row("SELECT id FROM t_payment_refunds WHERE payment_id=? AND active_slot=1 FOR UPDATE",input.paymentId())!=null)throw reject("REFUND_ALREADY_REQUESTED");
  var receipt=store.row("SELECT merchant_id,provider_transaction_id,payment_currency,payment_minor,payment_minor_digits,base_minor FROM t_currency_payment_receipts WHERE payment_id=? FOR UPDATE",input.paymentId());
  if(receipt==null||!Objects.equals(payment.get("merchant_id"),receipt.get("merchant_id"))||!Objects.equals(payment.get("provider_transaction_id"),receipt.get("provider_transaction_id"))||RefundStore.s(payment,"provider_transaction_id")==null||RefundStore.s(payment,"provider_transaction_id").isBlank()||!"CNY".equals(receipt.get("payment_currency"))||((Number)receipt.get("payment_minor_digits")).intValue()!=2||!RefundStore.minor(payment.get("payment_minor")).equals(RefundStore.minor(receipt.get("payment_minor")))||!RefundStore.minor(payment.get("base_minor")).equals(RefundStore.minor(receipt.get("base_minor"))))throw reject("REFUND_VERIFIED_SOURCE_REQUIRED");
  BigDecimal amount=new BigDecimal(payment.get("base_minor").toString()).movePointLeft(2).setScale(2);BigDecimal balance=money.lockBalance(user);if(balance==null||balance.compareTo(amount)<0)throw reject("REFUND_INSUFFICIENT_AVAILABLE_BALANCE");
  changed(store.db.update("INSERT INTO t_payment_refunds(id,payment_id,user_id,request_id,base_currency,base_minor,payment_currency,payment_minor,merchant_snapshot,provider_transaction_id,status,reason) VALUES(?,?,?,?,'CNY',?,'CNY',?,?,?,'requested',?)",id,input.paymentId(),user,request,payment.get("base_minor"),payment.get("payment_minor"),payment.get("merchant_snapshot"),payment.get("provider_transaction_id"),input.reason().trim()));
  if(money.addBalance(user,amount.negate(),"refund_reserve",null,"原充值退款预留；退款单 "+id)==null)throw new IllegalStateException("REFUND_WALLET_UNAVAILABLE");store.event(id,user,"requested","Full CNY recharge amount reserved; no provider dispatch");return store.refund(id);
 }
 @Transactional public Map<String,Object> review(String id,String actor,Review input){var locked=lock(id);var r=locked.refund();String target=input.approve()?"approved":"rejected";if(!"requested".equals(r.get("status"))){if(target.equals(r.get("status"))&&actor.equals(r.get("reviewed_by"))&&input.reason().trim().equals(r.get("review_note")))return r;throw reject("REFUND_REVIEW_CHANGED");}changed(store.db.update("UPDATE t_payment_refunds SET status=?,review_note=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP(3) WHERE id=? AND status='requested'",target,input.reason().trim(),actor,id));if(!input.approve())release(r,"审核驳回");store.event(id,actor,"reviewed",target);return store.refund(id);}
 @Transactional public Map<String,Object> cancel(String id,String user){var locked=lock(id);var r=locked.refund();if(!user.equals(r.get("user_id")))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"REFUND_NOT_FOUND");if("cancelled".equals(r.get("status")))return r;if(!"requested".equals(r.get("status")))throw reject("REFUND_CANCEL_NOT_ALLOWED");changed(store.db.update("UPDATE t_payment_refunds SET status='cancelled' WHERE id=? AND status='requested'",id));release(r,"用户撤回");store.event(id,user,"cancelled","Wallet reserve released");return store.refund(id);}
 /** CAS commits dispatch ownership before the chargeable request. Existing attempts are query-only forever. */
 @Transactional public Map<String,Object> claim(String id,String actor){var locked=lock(id);var r=locked.refund();if(!"approved".equals(r.get("status")))throw reject("REFUND_DISPATCH_NOT_ALLOWED");changed(store.db.update("UPDATE t_payment_refunds SET status='dispatching',dispatched_at=CURRENT_TIMESTAMP(3),last_error_code=NULL WHERE id=? AND status='approved'",id));store.event(id,actor,"dispatch_claimed","Provider request reserved once");return store.refund(id);}
 @Transactional public Map<String,Object> receipt(String id,Receipt receipt){var locked=lock(id);var r=locked.refund();if(!id.equals(receipt.refundId())||!Objects.equals(r.get("payment_id"),receipt.paymentId())||!Objects.equals(r.get("provider_transaction_id"),receipt.transactionId())||!"CNY".equals(receipt.currency())||!RefundStore.minor(r.get("payment_minor")).equals(receipt.totalMinor())||!RefundStore.minor(r.get("payment_minor")).equals(receipt.refundMinor())||receipt.providerRefundId()==null||receipt.providerRefundId().isBlank()||receipt.providerRefundId().length()>128)throw reject("REFUND_RECEIPT_MISMATCH");
  if(r.get("provider_refund_id")!=null&&!r.get("provider_refund_id").equals(receipt.providerRefundId()))throw reject("REFUND_PROVIDER_REFERENCE_CHANGED");
  String current=r.get("status").toString();if(Set.of("succeeded","closed").contains(current)){if(!current.equals(receipt.status()))throw reject("REFUND_TERMINAL_CONFLICT");return r;}if(!Set.of("dispatching","processing").contains(current)||!Set.of("processing","succeeded","closed").contains(receipt.status()))throw reject("REFUND_RECEIPT_STATE_REJECTED");
  if(Boolean.TRUE.equals(r.get("wallet_released"))||"1".equals(Objects.toString(r.get("wallet_released"))))throw reject("REFUND_RESERVE_ALREADY_RELEASED");changed(store.db.update("UPDATE t_payment_refunds SET status=?,provider_refund_id=?,last_error_code=NULL WHERE id=? AND status IN('dispatching','processing')",receipt.status(),receipt.providerRefundId(),id));if("closed".equals(receipt.status()))release(r,"渠道确认退款关闭");store.event(id,null,"provider_"+receipt.status(),"Verified original payment, amount, currency and refund reference");return store.refund(id);
 }
 @Transactional public void unconfirmed(String id){var locked=lock(id);if(Set.of("dispatching","processing").contains(locked.refund().get("status")))store.db.update("UPDATE t_payment_refunds SET last_error_code='REFUND_PROVIDER_UNCONFIRMED' WHERE id=? AND status IN('dispatching','processing')",id);}
 private void release(Map<String,Object> r,String reason){if(Boolean.TRUE.equals(r.get("wallet_released"))||"1".equals(Objects.toString(r.get("wallet_released"))))throw reject("REFUND_RESERVE_ALREADY_RELEASED");changed(store.db.update("UPDATE t_payment_refunds SET wallet_released=1 WHERE id=? AND wallet_released=0",r.get("id")));BigDecimal amount=new BigDecimal(r.get("base_minor").toString()).movePointLeft(2).setScale(2);if(money.addBalance(r.get("user_id").toString(),amount,"refund_release",null,reason+"；退款单 "+r.get("id"))==null)throw new IllegalStateException("REFUND_WALLET_UNAVAILABLE");}
}
